import argparse
import ast
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import sys
import tempfile

def encoded(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode()

def blob(data):
    return hashlib.sha1(("blob " + str(len(data)) + "\0").encode() + data).hexdigest()

def private(path):
    path.mkdir(parents=True, mode=0o700, exist_ok=True)
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or path.resolve() != path or info.st_uid != os.getuid() or info.st_mode & 0o077:
        raise RuntimeError("Use this operation's real private source directory")
    return path

def publish(path, data):
    private(path.parent)
    descriptor, temporary = tempfile.mkstemp(prefix=".source-", dir=path.parent)
    try:
        with os.fdopen(descriptor, "wb") as output:
            os.chmod(temporary, 0o600)
            output.write(data); output.flush(); os.fsync(output.fileno())
        try:
            os.link(temporary, path)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != data:
                raise RuntimeError("The retained original source changed: " + str(path))
    finally:
        Path(temporary).unlink(missing_ok=True)

def main():
    parser = argparse.ArgumentParser(description="Materialize the complete original Kafka customer operation")
    parser.add_argument("--root", required=True)
    parser.add_argument("--merchant-origin", default="https://kafka-workspace.example")
    parser.add_argument("--merchant-path", default="/events")
    args = parser.parse_args()
    if sys.version_info < (3, 11):
        raise RuntimeError("Use the selected original Python 3.11 or newer")
    os.umask(0o077)
    root = private(Path(args.root).expanduser().absolute())
    with os.fdopen(os.open(root / "source.lock", os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600), "r+b") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        identities, python_files = {}, []
        for group in ("files", "tools"):
            for name, item in PAYLOAD[group].items():
                parts = Path(name).parts
                if not parts or name.startswith("/") or ".." in parts:
                    raise RuntimeError("The original packet contains an invalid source path")
                data = item["content"].encode("utf-8")
                if blob(data) != item["sha"]:
                    raise RuntimeError("The embedded original source failed its Git identity: " + name)
                if name.endswith(".py"):
                    ast.parse(data, filename=name)
                    python_files.append(name)
                identities[(group + "/" + name)] = {"gitBlob": item["sha"], "bytes": len(data),
                    "sha256": hashlib.sha256(data).hexdigest()}
        source_root = private(root / "source")
        for name, item in PAYLOAD["files"].items():
            publish(source_root / name, item["content"].encode("utf-8"))
        for name, item in PAYLOAD["tools"].items():
            publish(root / name, item["content"].encode("utf-8"))
        inventory = {"schema": "stellar-forge.kafka-native-source-inventory.v1",
            "sourcePin": PAYLOAD["sourcePin"], "files": PAYLOAD["bindingFiles"],
            "merchantFiles": {name: value["sha"] for name, value in PAYLOAD["files"].items()}}
        publish(root / "source-inventory.json", encoded(inventory))
        merchant = {"origin": args.merchant_origin, "path": args.merchant_path,
            "payment": {"scheme": "exact", "network": "stellar:testnet",
                "asset": "CBIELTK6YBZJU5UP2WWQEUCYKLPU6AUNZ2BQ4WWFEIE3USCIHMXQDAMA",
                "amount": "10000",
                "payTo": "GDCPSCLRFZFT3RCAJ67DCNCTBQW3DLMRZYM4OWXCZI7J6XC3ZZKMGQOG",
                "maxTimeoutSeconds": 60}}
        publish(root / "merchant-request.json", encoded(merchant))
        result = {"schema": PAYLOAD["schema"], "operation": PAYLOAD["operation"], "sourcePin": PAYLOAD["sourcePin"],
            "status": "SOURCE_MATERIALIZED", "root": str(root), "sourceFiles": len(PAYLOAD["files"]),
            "originalBindingFiles": len(PAYLOAD["bindingFiles"]), "source": identities,
            "pythonParsed": python_files, "merchant": merchant}
        publish(root / "source-materialization.json", encoded(result))
        for directory, _children, _files in os.walk(root):
            if Path(directory) == root or Path(directory).is_relative_to(source_root):
                descriptor = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                try:
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
        print(json.dumps({key: result[key] for key in ("operation", "sourcePin", "status", "root",
            "sourceFiles", "originalBindingFiles")}), flush=True)
        return 0

if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as issue:
        print("Kafka source materialization: " + str(issue), file=sys.stderr, flush=True)
        sys.exit(1)
